{
  "packet_id": "H6-T01-3",
  "claim_id": "C050",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C050.component",
    "value": "If source dependence undermines a disputed feature, that feature should no longer be treated as established.",
    "scope": "Conditional withdrawal of established status; source dependence must undermine the feature rather than merely be mentioned.",
    "provenance": {
      "refs": [
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P032 explicitly supplies the condition and the withdrawal of established status."
    }
  },
  "signal_basis": {
    "component_id": "C050.signal_basis",
    "value": "Assessment of source access and copying identifies dependence that undermines support for the disputed feature.",
    "scope": "Dependence affecting the evidential basis of that specific feature, including shared authorship, copied timestamps, common clock errors or assumptions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P028",
          "role": "SUPPORT"
        },
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle supplies the source assessment, relevant forms of dependence, and the requirement that dependence undermine the disputed feature."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C050.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed for this bounded withdrawal of established status."
    }
  },
  "rationale": "Given dependence that undermines the feature's evidential support, withdrawing established status is warranted. This does not establish that the feature is false; it leaves competing explanations open.",
  "uncertainty": "The claim does not determine whether the disputed feature actually occurred. Mere source dependence without the stipulated undermining effect would not trigger it.",
  "anomalies": []
}
